async ({ workspace: { read }, git: { status, log }, shell: { execFile } }) => {
  const [skill, st, lg, au, prs] = await Promise.allSettled([
    read(".pi/skills/pit-delivery/SKILL.md", { format: "raw" }),
    status(["--short", "--branch"]),
    log(["--oneline", "-5"]),
    execFile("npm", ["audit", "--json"]),
    execFile("gh", ["pr", "list", "--state", "open", "--json", "number,title,headRefName,isDraft,mergeable,author"]),
  ]);
  return JSON.parse(JSON.stringify({ skill, st, lg, au: JSON.stringify(au).slice(0, 4000), prs })) as PitJsonValue;
}
